from typing import Union, Optional

from taf.rfrl.csv4all.resources.node.feature.fdsw.fdsw_node import FdswNode
from taf.rfrl.csv4all.resources.node.node_factory import NodeFactory
from taf.rfrl.csv4all.resources.utilities.decorators import function_wrapper
from taf.rfrl.csv4all.resources.utilities.utilities import test_logger
from taf.config.testline import ClassicalBts, RealEnb


class FdswNodeFactory(NodeFactory):

    @staticmethod
    @function_wrapper
    def create_node(node_alias: Optional[str] = None, node_vm: Union[str, dict] = None,
                    bts_host_ip: Optional[str] = "192.168.255.129",
                    external_dcap_host: Optional[str] = None, dcap_port: Optional[str] = "9443",
                    dcap_custom_profiles: Optional[dict] = None,
                    hw_to_onair_timeout: Optional[int] = 900, alarm_timer: Optional[int] = 60,
                    testline_object: Union[ClassicalBts, RealEnb] = None, source_sw: Optional[str] = None,
                    target_sw: Optional[str] = None, custom_allowed_alarms: Optional[list] = None,
                    temporary_allowed_alarms: Optional[list] = None, pdu_config: Optional[list] = None,
                    logs_dir: Optional[str] = None, use_dcap: Optional[bool] = False,
                    secondary_vm: Union[str, dict] = None, verify_syslog: Optional[bool] = True,
                    syslog_ignored_prints: Union[list, str] = None,
                    user_syslog_suspicious_prints: Union[list, str] = None,
                    mumin_config: Optional[list] = None, webem_username: str = 'Nemuadmin',
                    webem_password: str = 'nemuuser', node_ssh_username: str = "toor4nsn",
                    node_ssh_password: str = "oZPS0POrRieRtu", check_mplane: bool = True, airphone_details: dict = None,
                    check_amf: bool = True, admin_setup_timeout: int = 120, setup_energy_saving: bool = False,
                    ru_manager_yaml_file: Union[str, None] = None, **kwargs) -> FdswNode:
        args = locals()
        kwargs = args.get('kwargs')
        del args['kwargs']
        args.update(kwargs)
        node = FdswNode(**FdswNodeFactory._get_parsed_node_args(args))
        test_logger(f"Setup for node: {node.mrbts_id}")
        node.setup_node()
        node.log_node_information()
        return node

    @staticmethod
    def _get_parsed_node_args(node_args):
        base_node_args = NodeFactory._get_parsed_node_args(node_args)
        return base_node_args


